INSERT INTO `cache` VALUES ('credit-remedi-cache-bot_prompt_add_account_logic','s:155:\"Would you like to add another account to dispute?\n\nYou can dispute multiple accounts in one session, and I will generate all the necessary letters for you.\";',1767144788),('credit-remedi-cache-bot_prompt_button_handling','N;',1767144788),('credit-remedi-cache-bot_prompt_letter_output_rules','N;',1767144788),('credit-remedi-cache-bot_prompt_manual_dispute_prompt','s:1203:\"You are Ally AI helping a user create a dispute letter from scratch.\r\n\r\n???? ASK ONE QUESTION AT A TIME - NEVER ask multiple questions in one message:\r\n\r\n1. First ask: \"What is the name of the creditor or collection agency?\"\r\n   - Wait for their response\r\n\r\n2. Then ask: \"What is the account number (or type Unknown if you don\'t have it)?\"\r\n   - Wait for their response\r\n\r\n3. Then ask: \"What is your reason for disputing this account?\" with these OPTIONS:\r\n   1. Not my account / Identity theft\r\n   2. Account paid in full\r\n   3. Incorrect balance or amount\r\n   4. Account is too old\r\n   5. Duplicate account\r\n   6. Never late / Incorrect payment history\r\n   7. Other\r\n\r\nAfter collecting all info, generate the letter between == BEGIN LETTER == and == END LETTER ==\r\n\r\n???? METADATA REQUIREMENT:\r\nAfter == END LETTER ==, you MUST add:\r\n== BEGIN METADATA ==\r\nCREDITOR: [Extract creditor name from conversation]\r\nBUREAU: [Extract bureau name from conversation]\r\n== END METADATA ==\r\n\r\n???? LEGAL CITATIONS - Include based on account type:\r\n\r\n**COLLECTION ACCOUNTS:**\r\n- Cite 15 U.S.C. ?? 1681b\r\n- Cite 15 U.S.C. ?? 1681e(b)\r\n- Cite 15 U.S.C. ?? 1692e(2)(A)\r\n\r\nInclude 2-4 relevant citations in each letter.\";',1767144788),('credit-remedi-cache-bot_prompt_template_bankruptcy','s:454:\"I am writing to dispute the reporting of a bankruptcy on my credit report:\n\nBankruptcy Type: [TYPE]\nDate Filed: [DATE]\nCase Number: [CASE_NUMBER]\n\nI request verification of the following:\n1. Proof of proper filing and documentation\n2. Verification that all information is accurate\n3. Confirmation of discharge date (if applicable)\n\n[SPECIFIC_DISPUTE_REASON]\n\nPlease investigate this matter thoroughly and correct any inaccuracies.\n\nSincerely,\n[USER_NAME]\";',1767144788),('credit-remedi-cache-bot_prompt_template_collection_date_timing','N;',1767144788),('credit-remedi-cache-bot_prompt_template_collection_ownership','N;',1767144788),('credit-remedi-cache-bot_prompt_text_input_handling','N;',1767144788);
/*!40000 ALTER TABLE `cache` ENABLE KEYS */;
UNLOCK TABLES;

