          </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Current Address(es):\n                </td>\n                <td class=\"info\">\n                    <!-- ngRepeat: addr in addrs=(borrowerAddress|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}}) --><ng-repeat ng-repeat=\"addr in addrs=(borrowerAddress|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}})\" class=\"ng-scope\">\n                        <div>\n                            <!-- ngInclude: --><ng-include src=\"\'tucAddressTemplate\'\" onload=\"addr = addr\" class=\"ng-scope ng-binding\">\n        \n        <!-- ngIf: addressLine --><ng-if ng-if=\"addressLine\" class=\"ng-binding ng-scope\">\n            11835 203RD ST<br>\n        </ng-if><!-- end ngIf: addressLine -->\n        <!-- ngIf: (addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim) --><ng-if ng-if=\"(addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim)\" class=\"ng-binding ng-scope\">\n            SAINT ALBANS,&nbsp;NY<br>\n        </ng-if><!-- end ngIf: (addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim) -->\n        <!-- ngIf: addr.CreditAddress[\'@postalCode\'] --><ng-if ng-if=\"addr.CreditAddress[\'@postalCode\']\" class=\"ng-binding ng-scope\">\n            11412\n        </ng-if><!-- end ngIf: addr.CreditAddress[\'@postalCode\'] -->\n    </ng-include>\n                            <!-- ngIf: addr[\'@dateUpdated\'].indexOf(\'1900-01\')==-1 -->\n                        </div>\n                    </ng-repeat><!-- end ngRepeat: addr in addrs=(borrowerAddress|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}}) -->\n                    <ng ng-show=\"addrs.length==0\" class=\"ng-hide\">-</ng>\n                </td>\n                <td class=\"info\" ng-show=\"true\">\n                    <!-- ngRepeat: addr in addrs=(borrowerAddress|filter:{Source:{Bureau:{\'@symbol\':\'EXP\'}}}) --><ng-repeat ng-repeat=\"addr in addrs=(borrowerAddress|filter:{Source:{Bureau:{\'@symbol\':\'EXP\'}}})\" class=\"ng-scope\">\n                        <div>\n                            <!-- ngInclude: --><ng-include src=\"\'addressTemplate\'\" onload=\"addr = addr\" class=\"ng-scope\">\n        <!-- ngIf: addr.CreditAddress[\'@unparsedStreet\']|trim --><ng-if ng-if=\"addr.CreditAddress[\'@unparsedStreet\']|trim\" class=\"ng-binding ng-scope\">\n            14251 122ND AVE<br>\n        </ng-if><!-- end ngIf: addr.CreditAddress[\'@unparsedStreet\']|trim -->\n        <!-- ngIf: (addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim) --><ng-if ng-if=\"(addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim)\" class=\"ng-binding ng-scope\">\n            JAMAICA,&nbsp;NY<br>\n        </ng-if><!-- end ngIf: (addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim) -->\n        <!-- ngIf: addr.CreditAddress[\'@postalCode\'] --><ng-if ng-if=\"addr.CreditAddress[\'@postalCode\']\" class=\"ng-binding ng-scope\">\n            11436-1406\n        </ng-if><!-- end ngIf: addr.CreditAddress[\'@postalCode\'] -->\n    </ng-include>\n                            <!-- ngIf: addr[\'@dateUpdated\'].indexOf(\'1900-01\')==-1 --><div ng-if=\"addr[\'@dateUpdated\'].indexOf(\'1900-01\')==-1\" class=\"ng-binding ng-scope\">\n                                06/2023\n                            </div><!-- end ngIf: addr[\'@dateUpdated\'].indexOf(\'1900-01\')==-1 -->\n                        </div>\n                    </ng-repeat><!-- end ngRepeat: addr in addrs=(borrowerAddress|filter:{Source:{Bureau:{\'@symbol\':\'EXP\'}}}) -->\n                    <ng ng-show=\"addrs.length==0\" class=\"ng-hide\">-</ng>\n                </td>\n                <td class=\"info\" ng-show=\"true\">\n                    <!-- ngRepeat: addr in addrs=(borrowerAddress|filter:{Source:{Bureau:{\'@symbol\':\'EQF\'}}}) --><ng-repeat ng-repeat=\"addr in addrs=(borrowerAddress|filter:{Source:{Bureau:{\'@symbol\':\'EQF\'}}})\" class=\"ng-scope\">\n                        <div>\n                            <!-- ngInclude: --><ng-include src=\"\'addressTemplate\'\" onload=\"addr = addr\" class=\"ng-scope\">\n        <!-- ngIf: addr.CreditAddress[\'@unparsedStreet\']|trim --><ng-if ng-if=\"addr.CreditAddress[\'@unparsedStreet\']|trim\" class=\"ng-binding ng-scope\">\n            14251      122ND                      AVE<br>\n        </ng-if><!-- end ngIf: addr.CreditAddress[\'@unparsedStreet\']|trim -->\n        <!-- ngIf: (addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim) --><ng-if ng-if=\"(addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim)\" class=\"ng-binding ng-scope\">\n            JAMAICA,&nbsp;NY<br>\n        </ng-if><!-- end ngIf: (addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim) -->\n        <!-- ngIf: addr.CreditAddress[\'@postalCode\'] --><ng-if ng-if=\"addr.CreditAddress[\'@postalCode\']\" class=\"ng-binding ng-scope\">\n            11436\n        </ng-if><!-- end ngIf: addr.CreditAddress[\'@postalCode\'] -->\n    </ng-include>\n                            <!-- ngIf: addr[\'@dateUpdated\'].indexOf(\'1900-01\')==-1 -->\n                        </div>\n                    </ng-repeat><!-- end ngRepeat: addr in addrs=(borrowerAddress|filter:{Source:{Bureau:{\'@symbol\':\'EQF\'}}}) -->\n                    <ng ng-show=\"addrs.length==0\" class=\"ng-hide\">-</ng>\n                </td>\n            </tr>\n            <tr>\n                <td class=\"label\">\n                    Previous Address(es):\n                </td>\n                <td class=\"info\">\n                    <!-- ngRepeat: addr in addrs=(PreviousAddress|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}}) --><ng-repeat ng-repeat=\"addr in addrs=(PreviousAddress|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}})\" class=\"ng-scope\">\n                        <div>\n                            <!-- ngInclude: --><ng-include src=\"\'tucAddressTemplate\'\" onload=\"addr = addr\" class=\"ng-scope ng-binding\">\n        \n        <!-- ngIf: addressLine --><ng-if ng-if=\"addressLine\" class=\"ng-binding ng-scope\">\n            615 W 172ND ST 5G<br>\n        </ng-if><!-- end ngIf: addressLine -->\n        <!-- ngIf: (addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim) --><ng-if ng-if=\"(addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim)\" class=\"ng-binding ng-scope\">\n            NEW YORK,&nbsp;NY<br>\n        </ng-if><!-- end ngIf: (addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim) -->\n        <!-- ngIf: addr.CreditAddress[\'@postalCode\'] --><ng-if ng-if=\"addr.CreditAddress[\'@postalCode\']\" class=\"ng-binding ng-scope\">\n            10032\n        </ng-if><!-- end ngIf: addr.CreditAddress[\'@postalCode\'] -->\n    </ng-include>\n                            <!-- ngIf: addr[\'@dateUpdated\'].indexOf(\'1900-01\')==-1 -->\n                        </div>\n                    </ng-repeat><!-- end ngRepeat: addr in addrs=(PreviousAddress|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}}) --><ng-repeat ng-repeat=\"addr in addrs=(PreviousAddress|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}})\" class=\"ng-scope\">\n                        <div>\n                            <!-- ngInclude: --><ng-include src=\"\'tucAddressTemplate\'\" onload=\"addr = addr\" class=\"ng-scope ng-binding\">\n        \n        <!-- ngIf: addressLine --><ng-if ng-if=\"addressLine\" class=\"ng-binding ng-scope\">\n            11534 168TH ST 1<br>\n        </ng-if><!-- end ngIf: addressLine -->\n        <!-- ngIf: (addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim) --><ng-if ng-if=\"(addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim)\" class=\"ng-binding ng-scope\">\n            JAMAICA,&nbsp;NY<br>\n        </ng-if><!-- end ngI