ilter:{Source:{Bureau:{\'@symbol\':\'EQF\'}}}) --><ng-repeat ng-repeat=\"addr in addrs=(PreviousAddress|filter:{Source:{Bureau:{\'@symbol\':\'EQF\'}}})\" class=\"ng-scope\">\n                        <div>\n                            <!-- ngInclude: --><ng-include src=\"\'addressTemplate\'\" onload=\"addr = addr\" class=\"ng-scope\">\n        <!-- ngIf: addr.CreditAddress[\'@unparsedStreet\']|trim --><ng-if ng-if=\"addr.CreditAddress[\'@unparsedStreet\']|trim\" class=\"ng-binding ng-scope\">\n            11835      203RD                      ST<br>\n        </ng-if><!-- end ngIf: addr.CreditAddress[\'@unparsedStreet\']|trim -->\n        <!-- ngIf: (addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim) --><ng-if ng-if=\"(addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim)\" class=\"ng-binding ng-scope\">\n            SAINT ALBANS,&nbsp;NY<br>\n        </ng-if><!-- end ngIf: (addr.CreditAddress[\'@city\']|trim) || (addr.CreditAddress[\'@stateCode\']|trim) -->\n        <!-- ngIf: addr.CreditAddress[\'@postalCode\'] --><ng-if ng-if=\"addr.CreditAddress[\'@postalCode\']\" class=\"ng-binding ng-scope\">\n            11412\n        </ng-if><!-- end ngIf: addr.CreditAddress[\'@postalCode\'] -->\n    </ng-include>\n                            <!-- ngIf: addr[\'@dateUpdated\'].indexOf(\'1900-01\')==-1 -->\n                        </div>\n                    </ng-repeat><!-- end ngRepeat: addr in addrs=(PreviousAddress|filter:{Source:{Bureau:{\'@symbol\':\'EQF\'}}}) -->\n                    <ng ng-show=\"addrs.length==0\" class=\"ng-hide\">-</ng>\n                </td>\n            </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Employers:\n                </td>\n                <td class=\"info\">\n                    <!-- ngRepeat: emp in emps=(Employer|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}}) -->\n                    <ng ng-show=\"emps.length==0\">-</ng>\n                </td>\n                <td class=\"info\" ng-show=\"true\">\n                    <!-- ngRepeat: emp in emps=(Employer|filter:{Source:{Bureau:{\'@symbol\':\'EXP\'}}}) -->\n                    <ng ng-show=\"emps.length==0\">-</ng>\n                </td>\n                <td class=\"info\" ng-show=\"true\">\n                    <!-- ngRepeat: emp in emps=(Employer|filter:{Source:{Bureau:{\'@symbol\':\'EQF\'}}}) -->\n                    <ng ng-show=\"emps.length==0\">-</ng>\n                </td>\n            </tr>\n            <!--<tr>\n                <td class=\"label\">\n                    Consumer Comments:\n                </td>\n                <td class=\"info\">\n                    <ng-repeat ng-repeat=\"stmt in stmsts=(crdStmt|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}})\">\n                        {{stmt[\"@statement\"]|trim}}\n                    </ng-repeat>\n                    <ng ng-show=\"stmsts.length==0\">-</ng>\n                </td>\n                <td class=\"info\" ng-show=\"{{is3B}}\">\n                    <ng-repeat ng-repeat=\"stmt in stmsts=(crdStmt|filter:{Source:{Bureau:{\'@symbol\':\'EXP\'}}})\">\n                        {{stmt[\"@statement\"]|trim}}\n                    </ng-repeat>\n                    <ng ng-show=\"stmsts.length==0\">-</ng>\n                </td>\n                <td class=\"info\" ng-show=\"{{is3B}}\">\n                    <ng-repeat ng-repeat=\"stmt in stmsts=(crdStmt|filter:{Source:{Bureau:{\'@symbol\':\'EQF\'}}})\">\n                        {{stmt[\"@statement\"]|trim}}\n                    </ng-repeat>\n                    <ng ng-show=\"stmsts.length==0\">-</ng>\n                </td>\n            </tr>-->\n            <!--<tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Fraud Alert:\n                </td>\n                <td class=\"info\">\n                    <ng-if ng-if=\"Frozen[\'@transunion\']==\'true\'\">\n\n                    </ng-if>\n                    <ng ng-show=\"Frozen[\'@transunion\']==\'false\'\">-</ng>\n                </td>\n                <td class=\"info\" ng-show=\"{{is3B}}\">\n                    <ng-if ng-if=\"Frozen[\'@experian\']==\'true\'\">\n\n                    </ng-if>\n                    <ng ng-show=\"Frozen[\'@experian\']==\'false\'\">-</ng>\n                </td>\n                <td class=\"info\" ng-show=\"{{is3B}}\">\n                    <ng-if ng-if=\"Frozen[\'@equifax\']==\'true\'\">\n\n                    </ng-if>\n                    <ng ng-show=\"Frozen[\'@equifax\']==\'false\'\">-</ng>\n                </td>\n            </tr>-->\n        </tbody></table>\n    </div>\n    <div class=\"content_divider\">\n    </div>\n    <!--PersonInfo end-->\n    <!--credit score start-->\n    <div class=\"rpt_content_wrapper ng-binding\" id=\"CreditScore\">\n        <div class=\"rpt_fullReport_header\">\n            <span>Credit Score</span>\n            <span class=\"return_topSpan\">\n                <a href=\"javascript:void(0);\" onclick=\"scrollToSection(\'reportTop\')\" target=\"_self\">\n                    <span>Back to Top</span>\n                    <img src=\"https://member.identityiq.com/images/up-icon.svg\">\n                </a>\n            </span>\n        </div>\n        <table class=\"help_text\">\n            <tbody>\n                <tr>\n                    <td class=\"help_text_img\">\n                        <img src=\"https://member.identityiq.com/images/info-icon.svg\">\n                    </td>\n                    <td>\n                        Your Credit Score is a representation of your overall credit health. Most lenders\n                        utilize some form of credit scoring to help determine your credit worthiness.\n                    </td>\n                </tr>\n            </tbody>\n        </table>\n         \n         \n         \n        <table class=\"re-even-odd rpt_content_table rpt_content_header rpt_table4column\">\n            <tbody><tr>\n                <th>\n                </th>\n                <th class=\"headerTUC\">\n                    TransUnion\n                </th>\n                <th class=\"headerEXP\" ng-show=\"true\">\n                    Experian\n                </th>\n                <th class=\"headerEQF\" ng-show=\"true\">\n                    Equifax\n                </th>\n            </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Credit Score:\n                </td>\n                <td class=\"info ng-binding\">\n                    518\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    518\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    518\n                </td>\n            </tr>\n            <tr>\n                <td class=\"label\">\n                    Lender Rank:\n                </td>\n                <td class=\"info ng-binding\">\n                    Unfavorable\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    Unfavorable\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    Unfavorable\n                </td>\n            </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Score Scale:\n                </td>\n                <td class=\"info\">\n                    300-850\n                </td>\n                <td class=\"info\" ng-show=\"true\">\n                    300-850\n                </td>\n                <td class=\"info\" ng-show=\"true\">\n                    300-850\n                </td>\n            </tr>\n        </tbody></table>\n        <div ng-show=\"(TUCVantageScore.CreditScoreFactor &amp;&amp; TUCVantageScore.CreditScoreFactor.length&gt;0)|| (EXPVantageScore.CreditScoreFactor &amp;&amp; EXPVantageScore.CreditScoreFactor.length&gt;0)|| (EQFVantageScore.CreditScoreFactor &amp;&amp; EQFVantageScore.CreditScoreFactor.length&gt;0)\">\n            <div class=\"sub_header\">\n                Risk Factors\n                <!--<a href=\"#\" ng-click=\"showAllDescription(show);\" style=\"float: right; color: #fff;\">\n                    <ng ng-show=\"show\">hide all</ng>\n                    <ng ng-show=\"!show\">show all</ng>\n                </a>-->\n            </div>\n            <table class=\"rpt_content_table rpt_content_header rpt_content_contacts extra_info riskfactors\">\n                <tbody><tr>\n                    <td style=\"width: 25%;\" class=\"tuc_header\">\n                        TransUnion:\n                    </td>\n                    <td style=\"width: 75%;\" colspan=\"3\" class=\"info\">\n                        <!-- ngIf: (tucVScore|number)>=300 --><div ng-if=\"(tucVScore|number)&gt;=300\" class=\"ng-scope\">\n                            <!-- ngRepeat: factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor))\">\n                                <!-- ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') --><ng ng-if=\"factor[\'@bureauCode\']&amp;&amp;(factor[\'@FactorType\'] !=\'Positive\')\" class=\"ng-binding ng-scope\">\n                                    <!-- ngIf: factor.Factor[\'@description\'] -->\n                                    <!-- ngRepeat: txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor) --><span ng-repeat=\"txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor)\" class=\"ng-scope\">\n                                        <b class=\"ng-binding\">No open accounts in your credit file</b>\n                                    </span><!-- end ngRepeat: txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor) -->\n                                    \n                                    \n                                    <ng-if ng-show=\"!showDetail\" class=\"\">\n                                        <!-- ngRepeat: fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain --><span ng-repeat=\"fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain\" class=\"ng-binding ng-scope\">\n                                            The VantageScore credit score model relies on information in your credit files at the three national credit reporting companies (Equifax, Experian and TransUnion) to generate your score. Because you have no open accounts, your credit file does not contain enough information about your use of credit. A mix of different types of open and active credit accounts can have a positive impact on your credit score.\n                                        </span><!-- end ngRepeat: fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain -->\n                                        <!-- ngRepeat: txt in makeArray(factor.FactorText)|filter:isTUCFactorText -->\n                                    </ng-if>\n                                </ng><!-- end ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') -->\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor))\">\n                                <!-- ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') --><ng ng-if=\"factor[\'@bureauCode\']&amp;&amp;(factor[\'@FactorType\'] !=\'Positive\')\" class=\"ng-binding ng-scope\">\n                                    <!-- ngIf: factor.Factor[\'@description\'] -->\n                                    <!-- ngRepeat: txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor) --><span ng-repeat=\"txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor)\" class=\"ng-scope\">\n                                        <b class=\"ng-binding\">The date that you opened your oldest account is too recent</b>\n                                    </span><!-- end ngRepeat: txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor) -->\n                                    \n                                    \n                                    <ng-if ng-show=\"!showDetail\" class=\"\">\n                                        <!-- ngRepeat: fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain --><span ng-repeat=\"fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain\" class=\"ng-binding ng-scope\">\n                                            Your oldest account is still too recent. A credit file containing older accounts will have a positive impact on your credit score because it demonstrates that you are experienced managing credit.\n                                        </span><!-- end ngRepeat: fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain -->\n                                        <!-- ngRepeat: txt in makeArray(factor.FactorText)|filter:isTUCFactorText -->\n                                    </ng-if>\n                                </ng><!-- end ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') -->\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor))\">\n                                <!-- ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') --><ng ng-if=\"factor[\'@bureauCode\']&amp;&amp;(factor[\'@FactorType\'] !=\'Positive\')\" class=\"ng-binding ng-scope\">\n                                    <!-- ngIf: factor.Factor[\'@description\'] -->\n                                    <!-- ngRepeat: txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor) --><span ng-repeat=\"txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor)\" class=\"ng-scope\">\n                                        <b class=\"ng-binding\">Lack of sufficient relevant installment account information</b>\n                                    </span><!-- end ngRepeat: txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor) -->\n                                    \n                                    \n                                    <ng-if ng-show=\"!showDetail\" class=\"\">\n                                        <!-- ngRepeat: fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain --><span ng-repeat=\"fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain\" class=\"ng-binding ng-scope\">\n                                            An installment account is one with a fixed monthly payment for the life of the loan. Auto loans and student loans are common examples of installment loans. The VantageScore credit score model relies on information in your credit files at the three national credit reporting companies (Equifax, Experian and TransUnion) to generate your score. Your credit file does not contain enough information about your installment accounts. A mix of different types of open and active credit accounts, including installment accounts, can have a positive impact on your credit score.\n                                        </span><!-- end ngRepeat: fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain -->\n                                        <!-- ngRepeat: txt in makeArray(factor.FactorText)|filter:isTUCFactorText -->\n                                    </ng-if>\n                                </ng><!-- end ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') -->\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor))\">\n                                <!-- ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') --><ng ng-if=\"factor[\'@bureauCode\']&amp;&amp;(factor[\'@FactorType\'] !=\'Positive\')\" class=\"ng-binding ng-scope\">\n                                    <!-- ngIf: factor.Factor[\'@description\'] -->\n                                    <!-- ngRepeat: txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor) --><span ng-repeat=\"txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor)\" class=\"ng-scope\">\n                                        <b class=\"ng-binding\">You have too many delinquent or derogatory accounts</b>\n                                    </span><!-- end ngRepeat: txt in txtFs=(makeArray(factor.FactorText)|filter:isTUCFactorTextFactor) -->\n                                    \n                                    \n                                    <ng-if ng-show=\"!showDetail\" class=\"\">\n                                        <!-- ngRepeat: fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain --><span ng-repeat=\"fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain\" class=\"ng-binding ng-scope\">\n                                            You have had too many accounts with payments that are at least 30 days late and/or on which a lender has reported a derogatory status. Late payments are a proven indicator of increased risk. People with late payments are at risk of being overextended, putting existing credit with lenders at risk.\n                                        </span><!-- end ngRepeat: fText in makeArray(factor.FactorText)|filter:isTUCFactorTextExplain -->\n                                        <!-- ngRepeat: txt in makeArray(factor.FactorText)|filter:isTUCFactorText -->\n                                    </ng-if>\n                                </ng><!-- end ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') -->\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor))\">\n                                <!-- ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') -->\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor))\">\n                                <!-- ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') -->\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor))\">\n                                <!-- ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') -->\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor))\">\n                                <!-- ngIf: factor[\'@bureauCode\']&&(factor[\'@FactorType\'] !=\'Positive\') -->\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(TUCVantageScore.CreditScoreFactor)) -->\n                            <!-- ngIf: factors.length==0 -->\n                        </div><!-- end ngIf: (tucVScore|number)>=300 -->\n                        <!-- ngIf: (tucVScore|number)<300 -->\n                    </td>\n                </tr>\n                <tr class=\"rowAlt\" ng-show=\"true\">\n                    <td style=\"width: 25%;\" class=\"exp_header\">\n                        Experian:\n                    </td>\n                    <td style=\"width: 75%;\" colspan=\"3\" class=\"info\">\n                        <!-- ngIf: (expVScore|number)>=300 --><div ng-if=\"(expVScore|number)&gt;=300\" class=\"ng-scope\">\n                            <!-- ngRepeat: factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' --><ng ng-if=\"factor[\'@FactorType\'] !=\'Positive\'\" class=\"ng-binding ng-scope\">\n            \n            \n            <ng-if ng-show=\"!showDetail\">\n                <!-- ngRepeat: fText in makeArray(factor.FactorText) --><span ng-repeat=\"fText in makeArray(factor.FactorText)\" class=\"riskfactorsDetail ng-binding ng-scope\">No open accounts in your credit file </span><!-- end ngRepeat: fText in makeArray(factor.FactorText) -->\n            </ng-if>\n        </ng><!-- end ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' --><ng ng-if=\"factor[\'@FactorType\'] !=\'Positive\'\" class=\"ng-binding ng-scope\">\n            \n            \n            <ng-if ng-show=\"!showDetail\">\n                <!-- ngRepeat: fText in makeArray(factor.FactorText) --><span ng-repeat=\"fText in makeArray(factor.FactorText)\" class=\"riskfactorsDetail ng-binding ng-scope\">The date that you opened your oldest account is too recent </span><!-- end ngRepeat: fText in makeArray(factor.FactorText) -->\n            </ng-if>\n        </ng><!-- end ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' --><ng ng-if=\"factor[\'@FactorType\'] !=\'Positive\'\" class=\"ng-binding ng-scope\">\n            \n            \n            <ng-if ng-show=\"!showDetail\">\n                <!-- ngRepeat: fText in makeArray(factor.FactorText) --><span ng-repeat=\"fText in makeArray(factor.FactorText)\" class=\"riskfactorsDetail ng-binding ng-scope\">Lack of sufficient relevant installment account information </span><!-- end ngRepeat: fText in makeArray(factor.FactorText) -->\n            </ng-if>\n        </ng><!-- end ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' --><ng ng-if=\"factor[\'@FactorType\'] !=\'Positive\'\" class=\"ng-binding ng-scope\">\n            \n            \n            <ng-if ng-show=\"!showDetail\">\n                <!-- ngRepeat: fText in makeArray(factor.FactorText) --><span ng-repeat=\"fText in makeArray(factor.FactorText)\" class=\"riskfactorsDetail ng-binding ng-scope\">You have too many delinquent or derogatory accounts </span><!-- end ngRepeat: fText in makeArray(factor.FactorText) -->\n            </ng-if>\n        </ng><!-- end ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EXPVantageScore.CreditScoreFactor)) -->\n                            <!-- ngIf: factors.length==0 -->\n                        </div><!-- end ngIf: (expVScore|number)>=300 -->\n                        <!-- ngIf: (expVScore|number)<300 -->\n                    </td>\n                </tr>\n                <tr ng-show=\"true\">\n                    <td style=\"width: 25%;\" class=\"eqf_header\">\n                        Equifax:\n                    </td>\n                    <td style=\"width: 75%;\" colspan=\"3\" class=\"info\">\n                        <!-- ngIf: (eqfVScore|number)>=300 --><div ng-if=\"(eqfVScore|number)&gt;=300\" class=\"ng-scope\">\n                            <!-- ngRepeat: factor in factors=(makeArray(EQFVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EQFVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EQFVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EQFVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EQFVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EQFVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EQFVantageScore.CreditScoreFactor)) --><div class=\"descriptionTxt ng-scope\" ng-repeat=\"factor in factors=(makeArray(EQFVantageScore.CreditScoreFactor))\">\n                                <!-- ngInclude: --><ng-include src=\"\'scoreRiskFactorText\'\" onload=\"factor = factor\" class=\"ng-scope\">\n        <!-- ngIf: factor[\'@FactorType\'] !=\'Positive\' -->\n    </ng-include>\n                            </div><!-- end ngRepeat: factor in factors=(makeArray(EQFVantageScore.CreditScoreFactor)) -->\n                            <!-- ngIf: factors.length==0 -->\n                        </div><!-- end ngIf: (eqfVScore|number)>=300 -->\n                        <!-- ngIf: (eqfVScore|number)<300 -->\n                    </td>\n                </tr>\n                <tr>\n                    <td colspan=\"4\" class=\"info\" style=\"line-height: 18px;\">\n                        <div class=\"descriptionTxt\">\n                            <p>\n                                The score(s) on your IdentityIQ credit report (using the VantageScore® 3.0 model)\n                                are provided as a tool to help you understand how lenders may view the data contained\n                                in your credit reports and evaluate your credit risk. We provide these scores solely\n                                for educational purposes. IdentityIQ does not offer credit; delivery of these scores\n                                does not qualify you for any loan. The scoring model your lender uses may be different\n                                than the VantageScore® 3.0. As a result, the score and score factors we\n                                have delivered may show differences when compared to the score and score factors\n                                produced by your lender\'s scoring model. Please also understand that lenders use\n                                multiple sources of information when underwriting a loan and making lending decisions.\n                                Credit scores are just one factor that may be used and each lender will have different\n                                criteria they consider.\n                            </p>\n                            <p>\n                                IdentityIQ provides informational materials along with your credit report(s) and\n                                score(s) these materials are educational in nature and intended to broaden your\n                                understanding of how credit scoring works. They should not be construed as advice\n                                in handling your financial problems or making financial decisions. If you are having\n                                trouble keeping up with your bill payments or experiencing other financial difficulties,\n                                please contact a non-profit credit counseling service for assistance. These materials\n                                are for educational purposes only.\n                            </p>\n                        </div>\n                    </td>\n                </tr>\n            </tbody></table>\n        </div>\n    </div>\n    <div class=\"content_divider\">\n    </div>\n    <!--credit score end-->\n    <!--Summary starts-->\n    <div class=\"rpt_content_wrapper ng-binding\">\n        <div class=\"rpt_fullReport_header\" id=\"Summary\">\n            <span>Summary</span>\n            <span class=\"return_topSpan\">\n                <a href=\"javascript:void(0);\" onclick=\"scrollToSection(\'reportTop\')\" target=\"_self\">\n                    <span>Back to Top</span>\n                    <img src=\"https://member.identityiq.com/images/up-icon.svg\">\n                </a>\n            </span>\n        </div>\n          \n        \n        <table class=\"help_text\">\n            <tbody>\n                <tr>\n                    <td class=\"help_text_img\">\n                        <img src=\"https://member.identityiq.com/images/info-icon.svg\">\n                    </td>\n                    <td>\n                        Below is an overview of your present and past credit status including open and closed\n                        accounts and balance information.\n                    </td>\n                </tr>\n            </tbody>\n        </table>\n        <table class=\"re-even-odd rpt_content_table rpt_content_header rpt_table4column\">\n            <tbody><tr>\n                <th>\n                </th>\n                <th class=\"headerTUC\">\n                    TransUnion\n                </th>\n                <th class=\"headerEXP\" ng-show=\"true\">\n                    Experian\n                </th>\n                <th class=\"headerEQF\" ng-show=\"true\">\n                    Equifax\n                </th>\n            </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Total Accounts:\n                </td>\n                <td class=\"info ng-binding\">\n                    4\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    4\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    4\n                </td>\n            </tr>\n            <tr>\n                <td class=\"label\">\n                    Open Accounts:\n                </td>\n                <td class=\"info ng-binding\">\n                    0\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    0\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    0\n                </td>\n            </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Closed Accounts:\n                </td>\n                <td class=\"info ng-binding\">\n                    4\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    4\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    4\n                </td>\n            </tr>\n            <tr>\n                <td class=\"label\">\n                    Delinquent:\n                </td>\n                <td class=\"info ng-binding\">\n                    0\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    0\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    1\n                </td>\n            </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Derogatory:\n                </td>\n                <td class=\"info ng-binding\">\n                    1\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    1\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    1\n                </td>\n            </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Collection:\n                </td>\n                <td class=\"info ng-binding\">\n                    0\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    0\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    0\n                </td>\n            </tr>\n            <tr>\n                <td class=\"label\">\n                    Balances:\n                </td>\n                <td class=\"info ng-binding\">\n                    $6,884.00\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    $6,884.00\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    $6,884.00\n                </td>\n            </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Payments:\n                </td>\n                <td class=\"info\">\n                    <span class=\"Rsmall ng-binding\">\n                        $0.00\n                    </span>\n                </td>\n                <td class=\"info\" ng-show=\"true\">\n                    <span class=\"Rsmall ng-binding\">\n                        $0.00\n                    </span>\n                </td>\n                <td class=\"info\" ng-show=\"true\">\n                    <span class=\"Rsmall ng-binding\">\n                        $0.00\n                    </span>\n                </td>\n            </tr>\n            <tr>\n                <td class=\"label\">\n                    Public Records:\n                </td>\n                <td class=\"info ng-binding\">\n                    0\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    0\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    0\n                </td>\n            </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Inquiries(2 years):\n                </td>\n                <td class=\"info ng-binding\">\n                    0\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    0\n                </td>\n                <td class=\"info ng-binding\" ng-show=\"true\">\n                    0\n                </td>\n            </tr>\n        </tbody></table>\n    </div>\n    <div class=\"content_divider\">\n    </div>\n    <!--Summary ends-->\n    <!--Account history starts-->\n    <script type=\"text/ng-template\" id=\"tradeLinePartitionBasic\">\n        {{tradlines = makeArray(tpartition.Tradeline);\"\"}}\n        <div class=\"sub_header\">\n            {{tradlines[0][\'@creditorName\']}}\n            <ng ng-if=\"tpartition[\'@accountTypeSymbol\']==\'Y\'\">\n                &nbsp;(Original Creditor: {{tradlines[0].CollectionTrade[\'@originalCreditor\']}})\n            </ng>\n        </div>\n        <table class=\"re-even-odd rpt_content_table rpt_content_header rpt_table4column\">\n            <tr>\n                <th>\n                </th>\n                <th class=\"headerTUC\">\n                    TransUnion\n                </th>\n                <th class=\"headerEXP\" ng-show=\"{{is3B}}\">\n                    Experian\n                </th>\n                <th class=\"headerEQF\" ng-show=\"{{is3B}}\">\n                    Equifax\n                </th>\n            </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Account #:\n                </td>\n                <td class=\"info\">\n                    <ng-repeat ng-repeat=\"tradeline in tdls=(tradlines|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}})\">\n                        {{(tradeline[\'@accountNumber\'])||\"-\"}}\n                    </ng-repeat>\n                </td>\n                <td class=\"info\" ng-show=\"{{is3B}}\">\n                    <ng-repeat ng-repeat=\"tradeline in tdls=(tradlines|filter:{Source:{Bureau:{\'@symbol\':\'EXP\'}}})\">\n                        {{(tradeline[\'@accountNumber\'])||\"-\"}}\n                    </ng-repeat>\n                </td>\n                <td class=\"info\" ng-show=\"{{is3B}}\">\n                    <ng-repeat ng-repeat=\"tradeline in tdls=(tradlines|filter:{Source:{Bureau:{\'@symbol\':\'EQF\'}}})\">\n                        {{(tradeline[\'@accountNumber\'])||\"-\"}}\n                    </ng-repeat>\n                </td>\n            </tr>\n            <tr>\n                <td class=\"label\">\n                    Account Type:\n                </td>\n                <td class=\"info\">\n                    <ng-repeat ng-repeat=\"tradeline in tdls=(tradlines|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}})\">\n                        {{(tpartition[\'@accountTypeAbbreviation\'])||\"-\"}}\n                    </ng-repeat>\n                </td>\n                <td class=\"info\" ng-show=\"{{is3B}}\">\n                    <ng-repeat ng-repeat=\"tradeline in tdls=(tradlines|filter:{Source:{Bureau:{\'@symbol\':\'EXP\'}}})\">\n                        {{(tpartition[\'@accountTypeAbbreviation\'])||\"-\"}}\n                    </ng-repeat>\n                </td>\n                <td class=\"info\" ng-show=\"{{is3B}}\">\n                    <ng-repeat ng-repeat=\"tradeline in tdls=(tradlines|filter:{Source:{Bureau:{\'@symbol\':\'EQF\'}}})\">\n                        {{(tpartition[\'@accountTypeAbbreviation\'])||\"-\"}}\n                    </ng-repeat>\n                </td>\n            </tr>\n            <tr>\n                <td class=\"label\">\n                    Account Type - Detail:\n                </td>\n                <td class=\"info\">\n                    <ng-repeat ng-repeat=\"tradeline in tdls=(tradlines|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}})\">\n                        <ng ng-if=\"tpartition[\'@accountTypeSymbol\']==\'Y\'\">\n                            Collection\n                        </ng>\n                        <ng ng-if=\"tpartition[\'@accountTypeSymbol\']!=\'Y\'\">\n                            {{(tradeline.GrantedTrade.AccountType[\'@description\'])||\"-\"}}\n                        </ng>\n                    </ng-repeat>\n                </td>\n                <td class=\"info\" ng-show=\"{{is3B}}\">\n                    <ng-repeat ng-repeat=\"tradeline in tdls=(tradlines|filter:{Source:{Bureau:{\'@symbol\':\'EXP\'}}})\">\n                        <ng ng-if=\"tpartition[\'@accountTypeSymbol\']==\'Y\'\">\n                            Collection\n                        </ng>\n                        <ng ng-if=\"tpartition[\'@accountTypeSymbol\']!=\'Y\'\">\n                            {{(tradeline.GrantedTrade.AccountType[\'@description\'])||\"-\"}}\n                        </ng>\n                    </ng-repeat>\n                </td>\n                <td class=\"info\" ng-show=\"{{is3B}}\">\n                    <ng-repeat ng-repeat=\"tradeline in tdls=(tradlines|filter:{Source:{Bureau:{\'@symbol\':\'EQF\'}}})\">\n                        <ng ng-if=\"tpartition[\'@accountTypeSymbol\']==\'Y\'\">\n                            Collection\n                        </ng>\n                        <ng ng-if=\"tpartition[\'@accountTypeSymbol\']!=\'Y\'\">\n                            {{(tradeline.GrantedTrade.AccountType[\'@description\'])||\"-\"}}\n                        </ng>\n                    </ng-repeat>\n                </td>\n            </tr>\n            <tr class=\"rowAlt\">\n                <td class=\"label\">\n                    Bureau Code:\n                </td>\n                <td class=\"info\">\n                    <ng-repeat ng-repeat=\"tradeline in tdls=(tradlines|filter:{Source:{Bureau:{\'@symbol\':\'TUC\'}}})\">\n                        {{(tradeline.AccountDesignator[\'@description\'])||\"-\"}}\n                    </ng-repeat>\n                </td>\n                <td class=\"info\" ng-show=\"{{is3B}}\">\n                    <ng-repeat ng-repeat=\"tradeline in tdls=(tradlines|filter:{Source:{Bureau:{\'@symbol\':\'EXP\'}}})\">\n                        {{(tradeline.AccountDesignator[\'@description\'])||\"-\"}}\n                    </ng-repeat>\n                </td>\n      