--
-- Table structure for table `credit_scores`
--

DROP TABLE IF EXISTS `credit_scores`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `credit_scores` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `credit_report_id` bigint(20) unsigned NOT NULL,
  `bureau` varchar(255) NOT NULL,
  `score` int(11) NOT NULL,
  `score_model` varchar(255) DEFAULT 'VantageScore',
  `lender_rank` varchar(255) DEFAULT NULL,
  `score_scale` varchar(255) DEFAULT '300-850',
