DROP TABLE IF EXISTS `lenders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `lenders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `type` varchar(255) NOT NULL,
  `bureau_pull` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `min_credit_score` int(11) NOT NULL DEFAULT 0,
  `max_credit_score` int(11) NOT NULL DEFAULT 850,
  `recommended_score` varchar(255) DEFAULT NULL,
  `score_model` varchar(255) DEFAULT NULL,
  `min_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `max_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `min_apr` decimal(5,2) DEFAULT NULL,
  `max_apr` decimal(5,2) DEFAULT NULL,
  `intro_apr_months` int(11) DEFAULT NULL,
  `income_sensitivity` varchar(255) DEFAULT NULL,
  `inquiry_sensitivity` varchar(255) DEFAULT NULL,
  `application_url` varchar(255) DEFAULT NULL,
  `requirements` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`requirements`)),
  `notes` text DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

