--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `role` varchar(255) NOT NULL DEFAULT 'regular',
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `stripe_id` varchar(255) DEFAULT NULL,
  `pm_type` varchar(255) DEFAULT NULL,
  `pm_last_four` varchar(4) DEFAULT NULL,
  `trial_ends_at` timestamp NULL DEFAULT NULL,
  `has_paid` tinyint(1) NOT NULL DEFAULT 0,
  `plan_type` varchar(20) DEFAULT NULL COMMENT 'starter or premium',
  `registration_status` enum('pending','completed','failed') NOT NULL DEFAULT 'pending',
  `registration_error` text DEFAULT NULL,
  `payment_attempted_at` timestamp NULL DEFAULT NULL,
  `paid_amount` decimal(8,2) NOT NULL DEFAULT 0.00,
  `address` varchar(255) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `state` varchar(50) DEFAULT NULL,
  `zipcode` varchar(10) DEFAULT NULL,
  `contact_number` varchar(255) DEFAULT NULL,
  `ssn_last4` varchar(4) NOT NULL,
  `identityiq_username` varchar(255) DEFAULT NULL,
  `identityiq_password` varchar(255) DEFAULT NULL,
  `identityiq_secret_answer` varchar(255) DEFAULT NULL,
  `ai_analysis_completed` tinyint(1) NOT NULL DEFAULT 0,
  `identityiq_enrolled` tinyint(1) NOT NULL DEFAULT 0,
  `identityiq_enrolled_at` timestamp NULL DEFAULT NULL,
  `initial_report_uploaded` tinyint(1) NOT NULL DEFAULT 0,
  `initial_report_uploaded_at` timestamp NULL DEFAULT NULL,
  `onboarding_completed` tinyint(1) NOT NULL DEFAULT 0,
  `tour_completed` tinyint(1) DEFAULT 0,
  `onboarding_completed_at` timestamp NULL DEFAULT NULL,
  `ai_analysis_completed_at` timestamp NULL DEFAULT NULL,
  `ai_credits` int(11) NOT NULL DEFAULT 100,
  `profile_picture` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  KEY `users_stripe_id_index` (`stripe_id`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

