DROP TABLE IF EXISTS `waitlist_users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `waitlist_users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `challenge` varchar(255) NOT NULL,
  `usage` varchar(255) NOT NULL,
  `timeline` varchar(255) NOT NULL,
  `referrer_id` bigint(20) unsigned DEFAULT NULL,
  `referral_count` int(11) NOT NULL DEFAULT 0,
  `is_qualified` tinyint(1) NOT NULL DEFAULT 0,
  `referral_code` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `waitlist_users_email_unique` (`email`),
  UNIQUE KEY `waitlist_users_referral_code_unique` (`referral_code`)
) ENGINE=InnoDB AUTO_INCREMENT=159 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

